import{_ as t,o,c as i,al as a}from"./chunks/framework.7vp1BMOE.js";const _=JSON.parse('{"title":"Test MC_06 - Optical Flow","description":"","frontmatter":{},"headers":[],"relativePath":"ko/test_cards/mc_06_optical_flow.md","filePath":"ko/test_cards/mc_06_optical_flow.md"}'),r={name:"ko/test_cards/mc_06_optical_flow.md"};function l(n,e,s,c,h,d){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="test-mc-06-optical-flow" tabindex="-1">Test MC_06 - Optical Flow <a class="header-anchor" href="#test-mc-06-optical-flow" aria-label="Permalink to &quot;Test MC_06 - Optical Flow&quot;">​</a></h1><h2 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to &quot;Objective&quot;">​</a></h2><p>Test that optical flow works as expected</p><h2 id="preflight" tabindex="-1">Preflight <a class="header-anchor" href="#preflight" aria-label="Permalink to &quot;Preflight&quot;">​</a></h2><p>Disconnect all GPS / compasses and ensure vehicle is using optical flow for navigation (<a href="./../sensor/optical_flow">setup information here</a>)</p><p>Ensure there are no other sources of positioning besides optical flow:</p><ul><li><a href="./../advanced_config/parameter_reference#EKF2_OF_CTRL">EKF2_OF_CTRL</a>: <code>1</code></li><li><a href="./../advanced_config/parameter_reference#EKF2_GPS_CTRL">EKF2_GPS_CTRL</a>: <code>0</code></li><li><a href="./../advanced_config/parameter_reference#EKF2_EV_CTRL">EKF2_EV_CTRL</a>: <code>0</code></li></ul><p>Ensure that the drone can go into Altitude / Position mode while still on the ground</p><h2 id="flight-tests" tabindex="-1">Flight Tests <a class="header-anchor" href="#flight-tests" aria-label="Permalink to &quot;Flight Tests&quot;">​</a></h2><p>❏ <a href="./../flight_modes_mc/altitude">Altitude mode</a></p><p>    ❏ Vertical position should hold current value with stick centered</p><p>    ❏ Pitch/Roll/Yaw response 1:1</p><p>    ❏ Throttle response set to climb/descent rate</p><p>❏ <a href="./../flight_modes_mc/position">Position mode</a></p><p>    ❏ Horizontal position should hold current value with stick centered</p><p>    ❏ Vertical position should hold current value with stick centered</p><p>    ❏ Throttle response set to climb/descent rate</p><p>    ❏ Pitch/Roll/Yaw response set to pitch/roll/yaw rates</p><p>❏ Varying height terrain</p><p>    ❏ Put boxes on the ground to create varying heights in terrain</p><p>    ❏ Take off in position mode and fly over the boxes such that the downward facing rangefinder varies in value</p><p>    ❏ Do a few passes with varying amounts of time over the boxes (1-30 seconds if possible)</p><p>    ❏ Drone should not raise in height when flying over boxes</p><h2 id="착륙" tabindex="-1">착륙 <a class="header-anchor" href="#착륙" aria-label="Permalink to &quot;착륙&quot;">​</a></h2><p>❏ Land in either Position or Altitude mode with the throttle below 40%</p><p>❏ Upon touching ground, copter should disarm automatically within 2 seconds (default: see <a href="./../advanced_config/parameter_reference#COM_DISARM_LAND">COM_DISARM_LAND</a>)</p><h2 id="예상-결과" tabindex="-1">예상 결과 <a class="header-anchor" href="#예상-결과" aria-label="Permalink to &quot;예상 결과&quot;">​</a></h2><ul><li>추력을 올릴 때 서서히 이륙한다</li><li>Drone should hold altitude in Altitude mode without wandering (over surface with many features)</li><li>Drone should hold position within 1 meter in Position mode without pilot moving sticks</li><li>위에 언급한 어떤 비행 모드에서도 떨림이 나타나서는 안됨</li><li>Drone should not raise in height when flying over boxes</li><li>지면에 착륙시, 콥터가 지면에서 튀면 안됨</li></ul>',28)])])}const f=t(r,[["render",l]]);export{_ as __pageData,f as default};
